const dt=value=>value?new Date(value).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'}):'Belum pernah'
const statusLabel=value=>({ACTIVE:'Aktif',NEED_FOLLOW_UP:'Perlu ditinjau',NO_TRANSACTION:'Belum transaksi',PARTNERSHIP_ENDED:'Putus mitra'}[value]||value||'Belum transaksi')
const formOf=item=>item?.form||{}
const documentCount=item=>Object.values(item?.documents||{}).filter(doc=>doc?.image||doc?.dataUrl).length
const hasSignature=item=>Boolean(item?.agentConsent?.signature||item?.agentSignature?.image||item?.signature)
const normalizeIdentity=value=>String(value||'').trim().toLowerCase().replace(/\D/g,'')
const linkedAgentOf=(item,agents=[])=>{const form=formOf(item),userId=String(item?.userId||item?.user_id||'');return agents.find(agent=>String(agent.id)===userId)||agents.find(agent=>form.email&&String(agent.email||'').trim().toLowerCase()===String(form.email).trim().toLowerCase())||agents.find(agent=>form.whatsapp&&normalizeIdentity(agent.phone)===normalizeIdentity(form.whatsapp))||agents.find(agent=>form.agentName&&String(agent.name||'').trim().toLowerCase()===String(form.agentName).trim().toLowerCase())}
